fn column(lang: &str) -> Option<usize> {
    match lang.split(['-', '_']).next().unwrap_or("") {
        "pt" => Some(1),
        "es" => Some(2),
        _ => None,
    }
}

/// True when the interface is available in `lang` (English, the original, counts).
pub fn has_language(lang: &str) -> bool {
    let base = lang.split(['-', '_']).next().unwrap_or("").to_lowercase();
    base == "en" || column(&base).is_some()
}

struct Maps {
    /// [column] English -> translation
    forward: [HashMap<&'static str, &'static str>; 2],
    /// any translation -> English
    back: HashMap<&'static str, &'static str>,
}

fn maps() -> &'static Maps {
    static M: OnceLock<Maps> = OnceLock::new();
    M.get_or_init(|| {
        let mut m = Maps { forward: [HashMap::new(), HashMap::new()], back: HashMap::new() };
        for (en, pt, es) in TABLE.iter().copied() {
            m.forward[0].entry(en).or_insert(pt);
            m.forward[1].entry(en).or_insert(es);
            if pt != en {
                m.back.entry(pt).or_insert(en);
            }
            if es != en {
                m.back.entry(es).or_insert(en);
            }
        }
        m
    })
}

/// `text` in the language `lang` ("en", "pt", "pt-BR", "es"…), or None when nothing needs changing.
/// Works from English and also from any other language back to the requested one.
pub fn translate(lang: &str, text: &str) -> Option<&'static str> {
    let m = maps();
    let english: &str = m.back.get(text).copied().unwrap_or(text);
    let out = match column(lang) {
        Some(c) => *m.forward[c - 1].get(english)?,
        None => m.back.get(text).copied()?,
    };
    if out == text {
        None
    } else {
        Some(out)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn translates_both_ways() {
        assert_eq!(translate("pt-BR", "Library"), None.or(Some("Biblioteca")));
        assert_eq!(translate("es", "Discover"), Some("Descubrir"));
        assert_eq!(translate("en", "Biblioteca"), Some("Library"));
        assert_eq!(translate("es", "Descobrir"), Some("Descubrir"));
        assert_eq!(translate("en", "Library"), None);
        assert_eq!(translate("pt", "Something unknown"), None);
        assert_eq!(translate("fr", "Descobrir"), Some("Discover"));
    }
}
